import fs from "node:fs";
import { generatePrivateKey } from "viem/accounts";
import type { Address, Hex } from "viem";
import { loadConfig } from "./config.js";
import { StepError } from "./stepError.js";

export interface WorkshopState {
  /** Generated by step 1; devnet only. */
  participantKey?: Hex;
  foreign?: Address;
  wallet?: Address;
  paymaster?: Address;
  violating?: Address;
  lastTxHash?: Hex;
  /** The address of the key that ran step 1. Every other step checks it is still the participant key. */
  account?: Address;
  /** Names of the steps that finished, in the order they finished. */
  completedSteps?: string[];
}

const file = () => loadConfig().stateFile;

export function readState(): WorkshopState {
  try {
    return JSON.parse(fs.readFileSync(file(), "utf8")) as WorkshopState;
  } catch {
    return {};
  }
}

export function writeState(patch: Partial<WorkshopState>): void {
  fs.writeFileSync(file(), JSON.stringify({ ...readState(), ...patch }, null, 2) + "\n");
}

/** Step 1 starts the workshop over: everything is forgotten except the participant key, which the faucet funded. */
export function resetState(): void {
  const { participantKey } = readState();
  fs.writeFileSync(file(), JSON.stringify(participantKey ? { participantKey } : {}, null, 2) + "\n");
}

export function requireState<K extends keyof WorkshopState>(key: K, createdBy: string): NonNullable<WorkshopState[K]> {
  const v = readState()[key];
  if (v == null) {
    throw new StepError("STATE_MISSING", `No "${key}" in ${file()}`, { hint: `run \`yarn ${createdBy}\` first` });
  }
  return v as NonNullable<WorkshopState[K]>;
}

/** Returns the participant key from the state file, generating it there on first use. */
export function ensureParticipantKey(): Hex {
  const existing = readState().participantKey;
  if (existing) return existing;
  const key = generatePrivateKey();
  writeState({ participantKey: key });
  return key;
}
